INSERT INTO problem_reports (id, equipment_id, department, room, severity, status, reported_by, reported_role, reported_at, issue_description, assigned_technician_id, assigned_at, repair_notes, downtime_hours) VALUES
('TICK-1001', 'EQ-ICU-001', 'Intensive Care Unit (ICU)', 'ICU Pod 4 - Bed 12', 'Critical', 'Assigned', 'Nurse Practitioner Jenna Morales, RN', 'ICU Charge Nurse', '2026-09-13 07:15', 'During morning pre-use check, ventilator threw Error Code E-210 (Proximal Pressure Transducer Calibration Failure). Device fails internal pneumatic seal test and cannot initiate ventilation safely.', '11111111-1111-1111-1111-111111111111', '2026-09-13 07:35', ARRAY['07:45 - Biomedical dispatched to ICU with diagnostic tool and spare pressure transducer kit.', '08:20 - Confirmed sensor diaphragm contamination. Disassembling intake manifold for ultrasonic cleaning and transducer replacement.'], 2.5),
('TICK-1002', 'EQ-RAD-002', 'Radiology & Imaging', 'Radiology Suite 2B', 'High', 'In Repair', 'Tyler Higgins, RT(R)', 'Radiologic Technologist Lead', '2026-09-12 16:40', 'Collimator light field indicator bulb extinguished and tracking sensor drifting by 3 degrees. Routine diagnostic thoracic exposures paused for Suite 2B.', '22222222-2222-2222-2222-222222222222', '2026-09-12 17:10', ARRAY['17:30 - Collimator assembly opened. Replaced 150W halogen collimator lamp.', '09:00 - Optical alignment underway. Re-calibrating laser crosshair alignment using standard phantom grid.'], 17.2),
('TICK-1003', 'EQ-CARD-004', 'Cardiology', 'Cardiology Clinic - Exam 3', 'Medium', 'Reported', 'Dr. Aaron Meyer, MD', 'Attending Cardiologist', '2026-09-13 08:50', 'Lead V3 and V4 intermittently display artifact interference even with new disposable electrodes. Suspected hairline fracture in multi-conductor trunk cable.', '33333333-3333-3333-3333-333333333333', '2026-09-13 09:15', ARRAY['09:20 - Work order acknowledged. Replacement 10-lead shielded patient cable retrieved from biomedical parts depot.'], 1.0);
INSERT INTO maintenance_records (id, equipment_id, date, type, technician_id, description, parts_replaced, downtime_hours, cost, resolved_date, notes) VALUES
('MAINT-8801', 'EQ-ED-003', '2026-08-15', 'Preventive Maintenance', '33333333-3333-3333-3333-333333333333', 'Bi-annual electrical safety inspection and parameter calibration. Performed leakage current test (compliant with NFPA 99 standards). Calibrated NIBP transducer against mercury manometer.', ARRAY['SpO2 reusable sensor cable (Mindray #512F)', 'NIBP cuff tubing connector'], 1.5, 145, '2026-08-15 11:30', 'All physiological simulation waveforms passed within +/- 1% tolerance.'),
('MAINT-8802', 'EQ-CSSD-005', '2026-08-01', 'Preventive Maintenance', '44444444-4444-4444-4444-444444444444', 'Quarterly chamber door gasket replacement, clean steam generator electrode probes, and verified biological spore test indicator (Geobacillus stearothermophilus 10^6).', ARRAY['Silicone Door Gasket 3870', 'Safety Relief Valve 45 PSI'], 3.5, 380, '2026-08-01 15:45', 'Bowie-Dick test passed with uniform color change across all test sheet quadrants.'),
('MAINT-8803', 'EQ-ONC-007', '2026-08-22', 'Inspection', '33333333-3333-3333-3333-333333333333', 'Wireless connectivity firmware update to Guardrails safety software dataset v3.14. Pressure sensor limit tests executed across all 4 pump channels.', ARRAY['Pole clamp thumb screw', 'Internal Lithium coin backup cell'], 1.0, 45, '2026-08-22 14:15', 'Uploaded drug library checksum verified against Hospital Pharmacy formulary.'),
('MAINT-8804', 'EQ-LAB-008', '2026-08-05', 'Corrective Repair', '55555555-5555-5555-5555-555555555555', 'Pneumatic aspiration pinch valve 4 stuck in closed position due to reagent crystalline residue. Flushed reagent lines with enzymatic deproteinizer and replaced valve assembly.', ARRAY['Tygon tubing kit #4', 'Solenoid pinch valve 12VDC'], 4.5, 520, '2026-08-05 16:30', 'Ran 3-level quality control material (Low, Normal, High); CV% < 1.8% across WBC and RBC.'),
('MAINT-8805', 'EQ-ED-010', '2026-08-30', 'Calibration', '11111111-1111-1111-1111-111111111111', 'Annual energy discharge verification with Fluke Impulse 7000DP defibrillator analyzer. Tested energy output at 30J, 50J, 100J, 150J, and 200J into 50 ohm test load.', ARRAY['Pacing cable adapter', 'SurePower rechargeable battery pack'], 0.8, 290, '2026-08-30 10:20', 'Delivered energy precision within 2.1% of set target. Battery capacity verified at 100%.'),
('MAINT-8806', 'EQ-OR-009', '2026-07-02', 'Preventive Maintenance', '22222222-2222-2222-2222-222222222222', 'Full radiation output and beam filtration verification. Checked mechanical counterbalances, steering brakes, and laser positioning marker alignment.', ARRAY['C-Arm steering cable tension spring', 'Grounding strap'], 4.0, 410, '2026-07-02 18:00', 'Certified for surgical intraoperative fluoroscopy compliance with state radiation safety code.');
